import { useEffect, useState, useCallback } from 'react';
import { Link } from 'react-router-dom';
import { motion } from 'framer-motion';
import { Wifi, Download, Upload, Activity, MapPin, Server } from 'lucide-react';
import { ResponsiveContainer, AreaChart, Area, XAxis, Tooltip } from 'recharts';

function SpeedChecker() {
  const [download, setDownload] = useState(0);
  const [upload, setUpload] = useState(0);
  const [ping, setPing] = useState(0);
  const [testing, setTesting] = useState(false);
  const [history, setHistory] = useState([]);

  const API_BASE = process.env.REACT_APP_API_URL || 'http://localhost:5000';

  // Ping test - measures latency (multiple attempts for accuracy)
  const measurePing = useCallback(async () => {
    try {
      const pings = [];

      // Run 3 ping tests and take the average
      for (let i = 0; i < 3; i++) {
        const start = performance.now();
        await fetch(`${API_BASE}/api/ping`, { cache: 'no-store' });
        const end = performance.now();
        pings.push(end - start);
      }

      // Return average ping
      const avgPing = Math.floor(pings.reduce((a, b) => a + b) / pings.length);
      return avgPing;
    } catch (err) {
      console.error('Ping test failed:', err);
      return 0;
    }
  }, [API_BASE]);

  // Download test - matches fast.com methodology (4 parallel streams, time-based)
  const measureDownloadSpeed = useCallback(async () => {
    try {
      const isLocalhost = API_BASE.includes('localhost') || API_BASE.includes('127.0.0.1');
      const NUM_PARALLEL = 4; // 4 parallel connections like fast.com
      const TEST_DURATION = isLocalhost ? 3000 : 5000; // 3s localhost, 5s production (ms)
      const INITIAL_SIZE = 10 * 1024 * 1024; // Start with 10MB
      const speeds = [];

      console.log(`Starting download test - localhost: ${isLocalhost}, duration: ${TEST_DURATION}ms`);

      for (let run = 0; run < 2; run++) {
        let totalBytes = 0;
        const runStart = performance.now();

        // Keep downloading until test duration expires
        while (performance.now() - runStart < TEST_DURATION) {
          const batchStart = performance.now();

          // Download in parallel
          const promises = Array.from({ length: NUM_PARALLEL }).map(async () => {
            try {
              const size = INITIAL_SIZE;
              const response = await fetch(
                `${API_BASE}/api/download?size=${size}&t=${Date.now()}`,
                {
                  cache: 'no-store',
                  headers: {
                    Pragma: 'no-cache',
                    'Cache-Control': 'no-cache, no-store, must-revalidate',
                  },
                },
              );

              if (!response.ok) throw new Error(`Download failed: ${response.status}`);

              const buffer = await response.arrayBuffer();
              return buffer.byteLength;
            } catch (err) {
              console.error('Download error:', err.message);
              return 0;
            }
          });

          const results = await Promise.all(promises);
          totalBytes += results.reduce((sum, bytes) => sum + bytes, 0);

          // Check if we should continue or break early if we have enough data
          const elapsed = (performance.now() - runStart) / 1000;
          if (totalBytes > 50 * 1024 * 1024 && elapsed > 1) {
            // We have at least 50MB of data and 1 second has passed, that's enough
            break;
          }
        }

        const runDuration = (performance.now() - runStart) / 1000;
        const Mbps = (totalBytes * 8) / runDuration / 1000000;

        console.log(`Download run ${run}: ${totalBytes} bytes in ${runDuration.toFixed(2)}s = ${Mbps.toFixed(2)} Mbps`);

        if (totalBytes > 0) {
          speeds.push(Mbps);
        }
      }

      if (speeds.length === 0) {
        console.warn('No valid download speeds recorded');
        return 0;
      }

      const average = speeds.reduce((a, b) => a + b) / speeds.length;
      const final = Math.max(average, 0.1);

      console.log(`Download speeds: ${speeds.map((s) => s.toFixed(2))}, Final: ${final.toFixed(2)} Mbps`);
      return final;
    } catch (err) {
      console.error('Download test failed:', err);
      return 0;
    }
  }, [API_BASE]);

  // Upload test - time-based methodology (2 parallel uploads)
  const measureUploadSpeed = useCallback(async () => {
    try {
      const isLocalhost = API_BASE.includes('localhost') || API_BASE.includes('127.0.0.1');
      const NUM_PARALLEL = 2; // 2 parallel uploads
      const TEST_DURATION = isLocalhost ? 3000 : 5000; // 3s localhost, 5s production (ms)
      const CHUNK_SIZE = isLocalhost ? 5 * 1024 * 1024 : 10 * 1024 * 1024; // 5MB localhost, 10MB production
      const speeds = [];

      console.log(`Starting upload test - localhost: ${isLocalhost}, duration: ${TEST_DURATION}ms`);

      for (let run = 0; run < 2; run++) {
        let totalBytes = 0;
        const runStart = performance.now();

        // Keep uploading until test duration expires
        while (performance.now() - runStart < TEST_DURATION) {
          // Pre-generate fresh data for this batch
          const dataArrays = Array.from({ length: NUM_PARALLEL }).map(() => {
            const data = new Uint8Array(CHUNK_SIZE);
            window.crypto.getRandomValues(data);
            return data;
          });

          // Upload in parallel
          const promises = dataArrays.map((data) =>
            fetch(`${API_BASE}/api/upload-large?t=${Date.now()}`, {
              method: 'POST',
              headers: {
                'Content-Type': 'application/octet-stream',
                Pragma: 'no-cache',
                'Cache-Control': 'no-cache, no-store, must-revalidate',
              },
              body: data,
            })
              .then((res) => {
                if (!res.ok) throw new Error(`Upload failed: ${res.status}`);
                return res.json();
              })
              .then((result) => result.received || 0)
              .catch((err) => {
                console.error('Upload error:', err.message);
                return 0;
              }),
          );

          const results = await Promise.all(promises);
          totalBytes += results.reduce((sum, bytes) => sum + bytes, 0);

          // Check if we have enough data
          const elapsed = (performance.now() - runStart) / 1000;
          if (totalBytes > 30 * 1024 * 1024 && elapsed > 1) {
            // We have at least 30MB of data and 1 second has passed, that's enough
            break;
          }
        }

        const runDuration = (performance.now() - runStart) / 1000;
        const Mbps = (totalBytes * 8) / runDuration / 1000000;

        console.log(`Upload run ${run}: ${totalBytes} bytes in ${runDuration.toFixed(2)}s = ${Mbps.toFixed(2)} Mbps`);

        if (totalBytes > 0) {
          speeds.push(Mbps);
        }
      }

      if (speeds.length === 0) {
        console.warn('No valid upload speeds recorded');
        return 0;
      }

      const average = speeds.reduce((a, b) => a + b) / speeds.length;
      const final = Math.max(average, 0.1);

      console.log(`Upload speeds: ${speeds.map((s) => s.toFixed(2))}, Final: ${final.toFixed(2)} Mbps`);
      return final;
    } catch (err) {
      console.error('Upload test failed:', err);
      return 0;
    }
  }, [API_BASE]);

  const runTest = useCallback(async () => {
    try {
      console.log('=== SPEED TEST STARTED ===');
      setTesting(true);
      setDownload(0);
      setUpload(0);
      setPing(0);
      setHistory([]);

      // Step 1: Ping test
      console.log('Starting ping test...');
      const pingResult = await measurePing();
      console.log(`Ping result: ${pingResult}ms`);
      setPing(pingResult);

      // Step 2: Download speed test
      console.log('Starting download test...');
      const downloadSpeed = await measureDownloadSpeed();
      console.log(`Download speed: ${downloadSpeed.toFixed(2)} Mbps`);

      // Step 3: Upload speed test
      console.log('Starting upload test...');
      const uploadSpeed = await measureUploadSpeed();
      console.log(`Upload speed: ${uploadSpeed.toFixed(2)} Mbps`);
      console.log('=== SPEED TEST COMPLETED ===');

      // Animate to final values
      let current = 0;
      const downloadFinal = Number(downloadSpeed.toFixed(2));
      const uploadFinal = Number(uploadSpeed.toFixed(2));
      const step = Math.max(downloadFinal, uploadFinal) / 60;

      const interval = setInterval(() => {
        current += step;

        const downSpeed = Math.min(current, downloadFinal);
        const upSpeed = Math.min(current, uploadFinal);

        if (current >= Math.max(downloadFinal, uploadFinal)) {
          current = Math.max(downloadFinal, uploadFinal);
          clearInterval(interval);
          setTesting(false);
        }

        setDownload(downSpeed.toFixed(2));
        setUpload(upSpeed.toFixed(2));

        setHistory((prev) => [
          ...prev,
          {
            time: prev.length,
            speed: Number(downSpeed.toFixed(2)),
          },
        ]);
      }, 80);
    } catch (err) {
      console.error('Speed test error:', err);
      setTesting(false);
      alert(
        `Speed test failed: ${err.message}\n\nMake sure backend server is running on port 5000`,
      );
    }
  }, [measurePing, measureDownloadSpeed, measureUploadSpeed]);

  useEffect(() => {
    // Auto-run test on component mount
    const timer = setTimeout(() => runTest(), 500);
    return () => clearTimeout(timer);
  }, [runTest]);

  return (
    <div className="main-bg">
      <div className="container py-4">
        {/* HEADER */}
        <div className="topbar">
          <div className="d-flex align-items-center gap-3">
            <img src="/logo.png" alt="Speed Checker Logo" className="logo-img" style={{ height: '50px', width: 'auto' }} />
          </div>

          <button className="run-btn" onClick={runTest} disabled={testing}>
            {testing ? 'TESTING...' : 'RUN TEST'}
          </button>
        </div>

        {/* TOP CARDS */}
        <div className="row g-4 mt-1">
          <div className="col-6 col-lg-3">
            <MiniCard title="Download" value={`${download} Mbps`} icon={<Download />} />
          </div>

          <div className="col-6 col-lg-3">
            <MiniCard title="Upload" value={`${upload} Mbps`} icon={<Upload />} />
          </div>

          <div className="col-6 col-lg-3">
            <MiniCard title="Ping" value={`${ping} ms`} icon={<Activity />} />
          </div>

          <div className="col-6 col-lg-3">
            <MiniCard title="Status" value={testing ? 'Testing' : 'Stable'} icon={<Wifi />} />
          </div>
        </div>

        {/* MAIN PANEL */}
        <div className="glass-panel mt-4">
          {/* SPEED DISPLAY */}
          <motion.div
            key={download}
            initial={{ scale: 0.8, opacity: 0 }}
            animate={{ scale: 1, opacity: 1 }}
            className="speed-display"
          >
            <h1 className="speed-value">{download}</h1>
            <div className="speed-unit">Mbps</div>
          </motion.div>

          {/* GRAPH */}
          <div className="chart-box">
            <ResponsiveContainer width="100%" height={300}>
              <AreaChart data={history}>
                <defs>
                  <linearGradient id="colorSpeed" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#00f7ff" stopOpacity={0.8} />
                    <stop offset="95%" stopColor="#00f7ff" stopOpacity={0} />
                  </linearGradient>
                </defs>

                <XAxis dataKey="time" stroke="#6ecfff" />
                <Tooltip />

                <Area
                  type="monotone"
                  dataKey="speed"
                  stroke="#00f7ff"
                  fill="url(#colorSpeed)"
                  strokeWidth={3}
                />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* BOTTOM INFO */}
        <div className="row g-4 mt-1">
          <div className="col-md-4">
            <InfoCard title="Server" value="Local" icon={<Server />} />
          </div>

          <div className="col-md-4">
            <InfoCard title="Location" value="Your PC" icon={<MapPin />} />
          </div>

          <div className="col-md-4">
            <InfoCard title="Connection" value="Accurate" icon={<Wifi />} />
          </div>
        </div>

        {/* FOOTER */}
        <footer className="footer-section">
          <div className="footer-links">
            <Link to="/privacy-policy" className="footer-link">
              Privacy Policy
            </Link>
            <span className="separator">|</span>
            <Link to="/terms-of-service" className="footer-link">
              Terms of Service
            </Link>
            <span className="separator">|</span>
            <Link to="/disclaimer" className="footer-link">
              Disclaimer
            </Link>
            <span className="separator">|</span>
            <Link to="/about-us" className="footer-link">
              About Us
            </Link>
            <span className="separator">|</span>
            <Link to="/cookie-policy" className="footer-link">
              Cookie Policy
            </Link>
          </div>
          <p className="footer-copyright">
            © 2026 Speed Checker. All rights reserved. Powered by Speed Checker
          </p>
        </footer>
      </div>
    </div>
  );
}

function MiniCard({ title, value, icon }) {
  return (
    <div className="mini-card">
      <div className="mini-icon">{icon}</div>
      <div className="mini-title">{title}</div>
      <div className="mini-value">{value}</div>
    </div>
  );
}

function InfoCard({ title, value, icon }) {
  return (
    <div className="info-card">
      <div className="info-icon">{icon}</div>
      <div className="info-title">{title}</div>
      <div className="info-value">{value}</div>
    </div>
  );
}

export default SpeedChecker;
